        if(runtime_globals)return runtime_globals->read(index,simulation_clock?&*simulation_clock:nullptr);
        if(simulation_clock){if(const auto value=simulation_clock->global(index))return value;}
        if(index==9&&family_global)return family_global; // Actual legacy ActivateFamily authority.
