        const auto hour=incoming.get_data(session_context->travel_state->caller_neighbor_id,7);
        const auto minute=incoming.get_data(session_context->travel_state->caller_neighbor_id,8);
        if(!hour||!minute||*hour>23||*minute>59)throw odh::FormatError("temporary arrival hour/minute effects are missing or invalid");
        auto clock=simulation_clock->snapshot();clock.hour=static_cast<std::uint8_t>(*hour);clock.minute=static_cast<std::uint8_t>(*minute);
