    const auto actor_services_for=[&](std::int16_t id)->const ActorServiceEntry*{
        const auto found=actor_service_registry.find(id);
        if(found==actor_service_registry.end()||!world.is_live_reference(found->second.identity))return nullptr;
        const auto* entity=world.find(id);
        return entity&&entity->kind==odh::EntityKind::avatar&&!entity->ui_ghost?&found->second:nullptr;
    };
