    const auto primary_diagnostic=[&]()->std::string{return primary_runtime&&primary_runtime->vm?primary_runtime->vm->diagnostic():std::string{};};
    const auto primary_steps=[&]()->std::uint64_t{return primary_runtime&&primary_runtime->vm?primary_runtime->vm->steps():0;};
    const auto primary_frames=[&]()->const std::vector<odh::VmFrame>&{
        static const std::vector<odh::VmFrame> absent;
        return primary_runtime&&primary_runtime->vm?primary_runtime->vm->stack():absent;
    };
