            if(name.empty()||name.find_first_of("/\\:.")!=std::string::npos||name.find('\0')!=std::string::npos)
                throw odh::FormatError("NPC GLOB link is not a unique flat resource name");
            const auto entry=resolve_saved_semiglobal_entry(globals->archive,name+".iff");
            auto linked=load(Resource{globals->archive,entry,false},odh::RoutineScope::semiglobal);
            for(auto& routine:linked.routines)
                if(!actor->data.routines.emplace(routine.first,std::move(routine.second)).second)
                    throw odh::FormatError("NPC private and semiglobal routine keys overlap");
            actor->npc_semiglobal_tuning=std::move(linked.tuning);
            actor->npc_semiglobal=odh::SessionLinkedSemiglobal{entry.substr(0,entry.size()-4),
                session_resource_key(session_context->game_root,globals->archive),entry};
