        const auto body=strings.find(actor->data.startup->body_strings);
        if(body==strings.end())throw odh::FormatError("NPC body string table is absent");
        odh::NpcAvatarBodyInputs inputs;inputs.body=odh::parse_avatar_body_strings(body->second);
        const bool child=inputs.body->age&&*inputs.body->age<18;
        const auto walk=static_cast<std::uint16_t>(child?151:150);
        const auto swim=static_cast<std::uint16_t>(child?160:158);
        auto tables=load_strings(*globals,{walk,swim});
        if(!tables.count(walk)||!tables.count(swim))throw odh::FormatError("NPC global locomotion tables are absent");
        inputs.global_walk=std::move(tables.at(walk));inputs.global_swim=std::move(tables.at(swim));
        if(const auto special=strings.find(150);special!=strings.end())inputs.object_walk=std::move(special->second);
