    const auto install_persistent_entry_plan=[&](odh::Vm& thread,const odh::DefinitionCandidate& candidate,
            const SavedEntryPointVmCallPlan& plan){
        if(!session_context||!definition_index)return false;
        const bool linked=std::any_of(plan.owner_routines.begin(),plan.owner_routines.end(),
            [](const auto& item){return item.first.scope==odh::RoutineScope::semiglobal;});
        auto source=load_session_action_source(candidate,plan.function.action,{},session_context->game_root,
            globals,&*definition_index,linked);
        // Install a bank that the common resource loader can reconstruct.
        // Every routine used by the validated entry-point plan must be exact.
        odh::RoutineSet verified;
        for(const auto& item:plan.owner_routines){
            const auto found=source.routines.find(item.first);
            if(found==source.routines.end())return false;
            verified.emplace(found->first,found->second);
        }
        if(odh::session_loaded_bank_fingerprint(verified)!=
           odh::session_loaded_bank_fingerprint(plan.owner_routines))return false;
        const auto owner=plan.call.context.code_owner;
        const auto kind=source.linked_semiglobal?odh::SessionCodeBankKind::private_and_semiglobal:
            odh::SessionCodeBankKind::private_closure;
        auto provenance=session_resource_owner(owner,candidate,plan.function.action,kind,
            source.routines,source.linked_semiglobal);
        auto program=std::make_shared<const odh::VmProgram>(std::move(source.routines));
        if(resource_owner_provenance.count(owner)||!thread.install_shared_owner(owner,program))return false;
        resource_owner_provenance.emplace(owner,std::move(provenance));
        object_owner_programs.emplace(owner,std::move(program));
        saved_action_resources.emplace(owner,Resource{candidate.source,candidate.asset,candidate.asset.empty()});
        note_installed_resource_owner(thread,owner);
        return true;
    };
