            if(!motion_context_valid(context)||!render_lot||!render_lot->runtime_room_map())return {};
            const auto* actor=world.find(context.actor);
            if(!actor||actor->person_data.size()<=65)return {};
            const auto room=render_lot->runtime_room_at(context.position);
            const auto& rooms=render_lot->runtime_room_map()->rooms;
            const auto style=world.read(context.frame,3,17);
