                for(std::uint32_t n=0;n<7;++n)effects[n]=signed_word(neighbor_inventory->get_data(nid,n).value_or(0));
                for(std::size_t n=0;n<effects.size();++n)if(!world.set_motive(target->id,motive_indices[n],effects[n]))
                    throw odh::FormatError("travel sim-data motive application failed");
