            const auto* tracked=user_interactions.current(actor_id,uid);
            const auto identity=tracked?std::optional<odh::UserInteractionIdentity>{tracked->identity}:std::nullopt;
            auto* actor_vm=actor_vm_for(actor_id);
            const auto control=actor_vm?odh::resident_control_identity(world,*actor_vm,*actor_queue):std::nullopt;
            const auto result=control?odh::cancel_resident_action(world,*actor_vm,*actor_queue,*control,uid,
                &interaction_cancel_diagnostic):odh::InteractionCancelResult::unsupported;
