    const auto interaction_menu_layout=[&](std::uint32_t width,std::uint32_t height,
            std::array<std::int32_t,2> anchor,const std::vector<odh::PieMenuItem>& items){
#ifdef ODH_HAVE_LINUX_TEXT_RENDERER
        (void)items;
        const auto branch=interaction_menu_branch(width,height,anchor);
        return branch?std::optional<odh::PieMenuLayout>{branch->layout}:std::nullopt;
#else
        return odh::layout_pie_menu(width,height,anchor,items.size(),!render_pie_menu_path.empty(),render_pie_menu_selected);
#endif
    };
