    const auto draw_interaction_menu=[&](odh::RasterFrame& image){
#ifdef ODH_HAVE_LINUX_TEXT_RENDERER
        if(render_ground_selection&&render_menu_anchor&&!render_selection){
            const auto layout=ground_menu_layout(image.width,image.height);
            if(!layout)return;
            const auto target=render_pie_pointer.hover_target().value_or(layout->center);
            odh_host::draw_linux_pie_menu_head(image,*layout,
                render_pie_portrait?render_pie_portrait(*layout,target):nullptr);
            const auto* background=original_dialog_art?original_dialog_art->find("CPanel/PieFace1.bmp"):
                pie_menu_background?&*pie_menu_background:nullptr;
            odh_host::draw_linux_pie_menu(image,*layout,{ground_menu_caption},0,{},background,
                render_pie_pointer.pressed(),original_dialog_art?odh_host::PieMenuBackground::live_face:
                    odh_host::PieMenuBackground::diagnostic_generic);
            return;
        }
        if(!render_selection||!render_interactions||!render_interactions->table||!render_menu_anchor)return;
        const auto model=current_interaction_pie_menu();
        const auto* items=active_pie_menu_items(model);
        if(!items||items->empty())return;
        const auto anchor=render_menu_anchor.value_or(std::array<std::int32_t,2>{8,8});
        const auto branch=interaction_menu_branch(image.width,image.height,anchor);
        if(!branch)return;
        const auto* layout=&branch->layout;
        std::vector<odh_host::PieMenuCaption> captions(items->size());
        for(auto i=layout->page_first;i<items->size()&&i-layout->page_first<layout->page_size;++i){
            const auto& item=(*items)[i];
            captions[i]={pie_menu_item_label(item,false),item.label_language};
        }
        std::optional<odh_host::PieMenuCaption> parent_caption;
        if(layout->back_button){
            const odh::PieMenuItem* parent=nullptr;
            const std::vector<odh::PieMenuItem>* siblings=&model;
            for(const auto index:render_pie_menu_path){
                if(index>=siblings->size())break;
                parent=&(*siblings)[index];siblings=&parent->children;
            }
            if(!parent)return;
            parent_caption=odh_host::PieMenuCaption{pie_menu_item_label(*parent,false),parent->label_language};
        }
        const auto* background=original_dialog_art?original_dialog_art->find("CPanel/PieFace1.bmp"):
            pie_menu_background?&*pie_menu_background:nullptr;
        auto head_layout=*layout;
        head_layout.center=branch->head_center;
        auto target=branch->head_target.value_or(render_pie_pointer.hover_target().value_or(branch->head_center));
        if(!branch->head_target&&render_pie_keyboard_target){
            if(render_pie_menu_selected<layout->items.size()){
                const auto& option=layout->items[render_pie_menu_selected];
                if(option.width>0&&option.height>0)target={option.x+option.width/2,option.y+option.height/2};
            }
        }
        odh_host::draw_linux_pie_menu_head(image,head_layout,
            render_pie_portrait?render_pie_portrait(head_layout,target):nullptr);
        odh_host::draw_linux_pie_menu(image,*layout,captions,render_pie_menu_selected,parent_caption,background,
            render_pie_pointer.pressed(),original_dialog_art?odh_host::PieMenuBackground::live_face:
                odh_host::PieMenuBackground::diagnostic_generic);

#else
        (void)image;
#endif
    };
