        if(!caller||!actions||actor_vm_for(source_frame.context.caller)!=caller)
            return {odh::PrimitiveDisposition::unsupported,"autonomy needs exact resident VM and queue"};
        const auto* actor=world.frame_entity(source_frame,odh::VmEntityRole::caller);if(!actor)return {};
