            auto lifecycle=odh_host::make_session_object_position_services(std::move(context));
            if(!lifecycle.before_slot_transfer||!lifecycle.after_slot_transfer||!lifecycle.before_slot_transfer(root,room_change))
                fail("PrePositionChange incomplete: "+(lifecycle.lifecycle_diagnostic?lifecycle.lifecycle_diagnostic():std::string{}));
            scope->stage=Stage::check;
