    const auto collect_dead_execution_bodies=[&]()->bool{
        if(entity_scheduler.running()||active_object_constructions)return false;
        std::vector<odh::WorldEntityReference> roots;std::set<const odh::Vm*> visited;
        const auto append=[&](const auto& refs){roots.insert(roots.end(),refs.begin(),refs.end());};
        const auto thread=[&](const odh::Vm* value){
            if(!value||!visited.insert(value).second)return true;
            if(value->dispatch_active())return false;
            append(value->strong_entity_references());return true;
        };
        for(const auto& item:resident_interaction_threads){
            if(!thread(item.second.vm))return false;
            if(item.second.queue)append(item.second.queue->strong_entity_references());
        }
        for(const auto& item:runtime_object_threads)if(item.second&&!thread(item.second->vm.get()))return false;
        if(!thread(saved_phone_thread.get()))return false;
        if((!property_release_active||actor_services_for(runtime_avatar_id))&&primary_routing())append(primary_routing()->strong_entity_references());
        for(const auto* actor:auxiliary_actors)if(actor->routing)append(actor->routing->strong_entity_references());
        const auto context=[&](const odh::VmContext& value){
            for(const auto role:{odh::VmEntityRole::caller,odh::VmEntityRole::callee,odh::VmEntityRole::stack_object}){
                const auto ref=odh::vm_context_reference(value,role);if(ref.id>0&&ref.generation)roots.push_back(ref);
            }
        };
        if(!property_release_active||actor_services_for(runtime_avatar_id))
            for(const auto& portal:primary_portals().contexts)if(portal.second.pending_call)context(portal.second.pending_call->context);
        for(const auto* actor:auxiliary_actors)for(const auto& portal:actor->room_portals.contexts)
            if(portal.second.pending_call)context(portal.second.pending_call->context);
        for(const auto& pending:pending_create_objects)context(pending.source_frame.context);
        if(pending_vm_dialog){context(pending_vm_dialog->source.context);roots.push_back(pending_vm_dialog->thread_owner);}
        std::sort(roots.begin(),roots.end());roots.erase(std::unique(roots.begin(),roots.end()),roots.end());
        std::vector<odh::WorldEntityReference> collected;
        if(!world.collect_retained_bodies(roots,&collected))return false;
        original_constructor_metadata.collect(world);
        if(relationships)for(const auto& ref:collected)
            if(!relationships->forget_object_source(ref.id,ref.generation))return false;
        if(live_dynamic_groups&&!live_dynamic_groups->collect_retired_native_members())return false;
        return true;
    };
    std::function<std::optional<std::int32_t>()> capture_house_property_value;
