    const auto household_selector_portrait=[&](std::int16_t runtime_id,std::uint32_t guid)
        ->const odh_host::HouseholdSelectorPortrait* {
        SceneRenderer* renderer=nullptr;
        const odh::AvatarBodyDescriptor* descriptor=nullptr;
        std::vector<std::string> bound;
        auto* cache=&household_portrait_cache;
        if(runtime_id==runtime_avatar_id){
            renderer=render_renderer.get();
            if(primary_body())descriptor=&*primary_body();
            if(const auto* live=world.find(runtime_id))bound=live->bound_appearances;
        }else{
            const auto* member=actor_runtime_for(runtime_id);
            if(!member)return nullptr;
            renderer=member->scene_renderer.get();
            if(member->body_state)descriptor=&*member->body_state;
            if(std::none_of(household_runtime.begin(),household_runtime.end(),[&](const auto& resident){
                return resident->id==runtime_id;}))cache=&npc_portrait_cache;
            if(const auto* live=world.find(runtime_id))bound=live->bound_appearances;
        }
        if(!renderer||!descriptor||!descriptor->body)return nullptr;
        const auto& body_name=descriptor->body->body;
        const auto& head_name=descriptor->body->head;
        const auto cached=cache->find(runtime_id);
        if(cached!=cache->end()&&cached->second.guid==guid&&
           cached->second.renderer==renderer&&cached->second.body==descriptor&&
           cached->second.body_name==body_name&&cached->second.head_name==head_name&&
           cached->second.bound_appearances==bound)
            return cached->second.available?&cached->second.pixels:nullptr;
        if(cached==cache->end()&&cache->size()>=8){
            if(cache==&household_portrait_cache)return nullptr;
            cache->erase(cache->begin()); // NPC tiles consume their portrait immediately.
        }
        auto& entry=(*cache)[runtime_id];
        entry.guid=guid;entry.renderer=renderer;entry.body=descriptor;
        entry.body_name=body_name;entry.head_name=head_name;entry.bound_appearances=bound;
        entry.available=false;
        try{
#ifdef ODH_HAVE_LINUX_TEXT_RENDERER
            // Installed characters already carry the original face icons. Use
            // those exact pixels; procedural heads only fill a missing cache.
            const auto* icons=ui_neighbor_portraits?ui_neighbor_portraits->images(guid):nullptr;
            if(ui_neighbor_portraits&&ui_neighbor_portraits->failed(guid))return nullptr;
            const auto* authored=icons&&!icons->faces.empty()?&icons->faces[0]:nullptr;
            if(authored){
                entry.panel_head=*authored;entry.authored_icon=true;
                odh::RasterFrame icon;icon.width=74;icon.height=74;icon.pixels.assign(74*74,{0,0,80,255});
                odh::blit_color_keyed_bitmap(icon,*authored,(74-int(authored->width))/2,
                    (74-int(authored->height))/2,{255,0,255});
                std::copy(icon.pixels.begin(),icon.pixels.end(),entry.pixels.begin());
                entry.available=true;return &entry.pixels;
            }
#endif
            entry.authored_icon=false;
            const auto rendered=renderer->render_head_portrait(SceneState{},original_frontal_portrait_camera());
            if(rendered.image.width!=74||rendered.image.height!=74||rendered.image.pixels.size()!=74U*74U)
                throw odh::FormatError("household portrait renderer returned an invalid image");
            if(rendered.image.depth.size()!=rendered.image.pixels.size())
                throw odh::FormatError("household portrait coverage unavailable");
            std::copy(rendered.image.pixels.begin(),rendered.image.pixels.end(),entry.pixels.begin());
            entry.panel_head=odh::BitmapImage{74,74,24,true,rendered.image.pixels,0};
            for(std::size_t i=0;i<rendered.image.depth.size();++i)
                if(!std::isfinite(rendered.image.depth[i]))entry.panel_head->pixels[i]={255,0,255,255};
            entry.available=true;
        }catch(const std::exception& error){
#ifdef ODH_HAVE_LINUX_SESSION_LOG
            session_log.event("household selector portrait unavailable Sim="+
                std::to_string(runtime_id)+" reason="+error.what());
#else
            (void)error;
#endif
        }
        return entry.available?&entry.pixels:nullptr;
    };
