    const auto draw_player_queue=[&](odh::RasterFrame& image){
        player_queue_tiles.clear();
#ifdef ODH_HAVE_LINUX_TEXT_RENDERER
        const auto* queue=actor_queue_for(active_household_actor);
        if(!queue||!session_context)return;
        const auto snapshot=queue->snapshot();
        const auto* actor=world.find(snapshot.actor_id);
        std::optional<std::int16_t> active_priority;
        if(actor&&actor->generation==snapshot.actor_generation&&actor->kind==odh::EntityKind::avatar&&actor->person_data.size()>33)
            active_priority=actor->person_data[33];
        player_queue_tiles=odh_host::original_queue_layout(snapshot,image.width,image.height,active_priority);
        if(!player_request_message.empty()){
            odh_host::TextOverlayStyle notice;notice.x=8;notice.y=player_queue_tiles.empty()?8:player_queue_tiles.back().box.y+46;
            notice.height=24;notice.width=std::min<int>(300,image.width-8);notice.font_size_px=12;
            (void)odh_host::draw_text_overlay(image,player_request_message,game_language,notice);
        }
        if(player_queue_tiles.empty())return;
        if(!queue_view)queue_view.emplace(session_context->game_root);
        for(auto& tile:player_queue_tiles){
            const auto& action=snapshot.actions[tile.action_index];
            const auto owner=action.icon_owner.value_or(odh::InteractionIconOwnerSnapshot{
                action.call.context.callee,action.target_generation});
            const auto* entity=world.is_live_reference({owner.id,owner.generation})?world.find(owner.id):nullptr;
            const odh::BitmapImage* thumbnail=nullptr;
            std::optional<odh::BitmapImage> portrait;
            if(entity&&entity->definition){
                if(entity->kind==odh::EntityKind::avatar){
                    const auto* icons=ui_neighbor_portraits?ui_neighbor_portraits->images(entity->definition->guid):nullptr;
                    if(icons&&icons->thumbnail)thumbnail=&*icons->thumbnail;
                    else if(const auto* pixels=household_selector_portrait(entity->id,entity->definition->guid)){
                        portrait=odh::BitmapImage{74,74,24,true,{pixels->begin(),pixels->end()},0};
                        thumbnail=&*portrait;
                    }
                }else if(definition_index)thumbnail=queue_view->object_icon(*definition_index,entity->definition->guid);
            }
            const auto* tracked=user_interactions.find(tile.identity);
            if(tracked&&tracked->cancellation_requested)tile.cancelled=true;
            queue_view->draw_tile(image,tile,thumbnail);
        }
        if(queue_pointer&&!pending_vm_dialog&&!nonblocking_vm_dialog&&!household_selector_open&&!render_menu_anchor){
            const auto* tile=odh_host::queue_tile_at(player_queue_tiles,(*queue_pointer)[0],(*queue_pointer)[1]);
            if(tile){
                const auto& action=snapshot.actions[tile->action_index];
                const auto label=player_request_label(odh::UserInteractionRequest{tile->identity,action});
                odh_host::TextOverlayStyle style;style.width=std::min<int>(240,image.width);
                style.x=std::min(tile->box.x,static_cast<int>(image.width)-style.width);
                style.y=tile->box.y+tile->box.height;style.height=24;style.font_size_px=12;
                try{const auto text=odh_host::legacy_text_to_utf8(label.first,label.second,2048);
                    (void)odh_host::draw_text_overlay(image,text,label.second,style);}
                catch(const std::exception&){/* Unavailable text does not change the selected action. */}
            }
        }
#else
        (void)image;
#endif
    };
