    const auto pickup_permission=[&](odh::ObjectTradeIdentity target,bool deleting,bool verify_transaction=true){
        try{
            const auto groups=live_physical_groups();
            std::vector<odh::ObjectTradeAvatarThread> threads;
            bool complete=true;
            for(std::int16_t id=0;;){const auto next=world.next_entity(id);if(!next)break;id=*next;
                const auto* e=world.find(id);if(e->kind!=odh::EntityKind::avatar)continue;
                const auto* actor=actor_runtime_for(id);
                if(!actor||!actor->vm){complete=false;continue;}
                threads.push_back({{id,e->generation},actor->vm.get()});
            }
            std::optional<odh::ObjectTradeBuildableArea> buildable;
            if(render_lot&&render_lot->prepared_architecture()){
                const auto& p=*render_lot->prepared_architecture();
                buildable=odh::ObjectTradeBuildableArea{p.width,p.height,5,0,0,int(p.width),int(p.height),
                    std::vector<bool>(p.buildable.begin(),p.buildable.end())};
            }
            std::optional<std::uint8_t> disabled;
            if(object_values)if(const auto* group=object_values->query(target))
                for(const auto& member:group->members)
                    if(member.object.id==target.id&&member.object.generation==target.generation){
                        disabled=member.disabled;break;
                    }
            const auto created=created_object_origins.find(target.id);
            if(!disabled&&created!=created_object_origins.end()&&created->second.generation==target.generation)disabled=0;
            return odh::ts1_object_trade_permission({world,target,groups,threads,complete,buildable,false,deleting,disabled,verify_transaction});
        }catch(const odh::FormatError&){
            return odh::ObjectTradeDecision{odh::ObjectTradeStatus::unresolved,odh::ObjectTradeReason::incomplete_group,target.id};
        }
    };
    buy_services.object_pick=[&](std::int32_t x,std::int32_t y)->std::optional<odh::BuyModeExistingObject>{
        if(!render_lot||!render_lot_evidence)return {};
        const auto selected=render_lot->pick(*render_lot_evidence,x,y);
        if(!selected)return {};
        const auto* object=world.find(selected->id);
        if(!object||object->generation!=selected->generation||!object->definition||
           object->definition->guid!=selected->guid||!object->position)return {};
        const auto physical=live_physical_manifest({object->id,object->generation});if(!physical)return {};
        const auto* base=world.find(physical->base_id);
        if(!base||!base->position||base->position->level!=render_lot_view.level)return {};
        // Source holder filters by BaseObject; backend commands retain the
        // clicked identity (including EP12/Disabled for a delete command).
        const auto permission=pickup_permission({base->id,base->generation},false,false);
        if(permission.status!=odh::ObjectTradeStatus::allowed){
#ifdef ODH_HAVE_LINUX_SESSION_LOG
            session_log.event("UI pickup refused id="+std::to_string(object->id)+" reason="+std::to_string(static_cast<unsigned>(permission.reason)));
#endif
            return {};
        }
        const odh::VmFrame frame{odh::routine_key(4096),0,{object->id,object->id,object->id,0},{},{}};
        odh::BuyModeExistingObject result{{object->id,object->generation},selected->guid,*base->position,
            world.read(frame,3,0),{}};
        result.dynamic_sprite_flags=odh::dynamic_sprite_flag_values(*object);
        odh::BuyModePreviewGroup preview;
        std::optional<std::int16_t> selected_native_heading;
        if(physical->native_head){
            const auto* native_head=world.resolve_reference(*physical->native_head);
            const auto selected_heading=object->object_words.find(1);
            if(!native_head||!world.is_live_reference(*physical->native_head)||selected_heading==object->object_words.end()||
               selected_heading->second<0||selected_heading->second>7||object->position->direction!=selected_heading->second)return {};
            const auto head_heading=native_head->object_words.find(1);
            if(head_heading==native_head->object_words.end()||head_heading->second<0||head_heading->second>7)return {};
            selected_native_heading=selected_heading->second;
            preview.native_selected_heading=static_cast<std::uint8_t>(*selected_native_heading);
            preview.native_head_heading_delta=static_cast<std::uint8_t>((head_heading->second-*selected_native_heading+8)&7);
            result.position=*object->position; // Native SetPosition anchors the selected piece.
        }
        for(const auto& part:physical->members){const auto* entity=world.find(part.id);
            if(!entity||entity->generation!=part.generation||!entity->definition)return {};
            const odh::VmFrame address{odh::routine_key(4096),0,{entity->id,entity->id,entity->id,0},{},{}};
            const auto graphic=world.read(address,3,0);if(!graphic)return {};
            odh::BuyModePreviewPart visual{entity->definition->guid,part.offset_x,part.offset_y,part.offset_level,*graphic,{}};
            if(selected_native_heading){
                const auto heading=entity->object_words.find(1);
                if(!part.native||heading==entity->object_words.end()||heading->second<0||heading->second>7)return {};
                visual.native=odh::BuyModeNativePreviewPart{part.native->authored,
                    static_cast<std::uint8_t>((heading->second-*selected_native_heading+8)&7),part.native->current};
            }
            visual.dynamic_sprite_flags=odh::dynamic_sprite_flag_values(*entity);
            if(part.id==(selected_native_heading?object->id:physical->base_id))preview.base_index=preview.parts.size();
            preview.parts.push_back(std::move(visual));
        }
        result.preview_group=std::move(preview);return result;
    };
    buy_services.existing_info=[&](odh::ObjectTradeIdentity target)->std::optional<odh_host::BuyModeExistingInfo>{
        const auto* object=world.find(target.id);
        if(!object||object->generation!=target.generation||!object->definition||!definition_index||!session_context)return {};
        const auto* candidate=definition_index->unique(object->definition->guid);if(!candidate)return {};
        odh_host::BuyModeExistingInfo info;info.content.target=target;
        odh_host::BuyTextDecoder decode;
#ifdef ODH_HAVE_LINUX_TEXT_CODEC
        decode=[](std::string_view value,std::uint8_t language){return odh_host::legacy_text_to_utf8(std::string(value),language);};
#endif
        info.content.name=odh_host::resolve_object_pickup_name(*candidate,*definition_index,game_language,decode).value_or("");
        const auto physical=live_physical_manifest({target.id,target.generation});
        const auto* base=physical?world.find(physical->base_id):nullptr;
        const auto permission=base?pickup_permission({base->id,base->generation},true,false):
            odh::ObjectTradeDecision{odh::ObjectTradeStatus::unresolved,odh::ObjectTradeReason::incomplete_group,target.id};
        if(permission.status!=odh::ObjectTradeStatus::unresolved)
            info.content.can_sell=permission.status==odh::ObjectTradeStatus::allowed;
        if(object_values)if(const auto* value=object_values->query(target)){
            const auto member=std::find_if(value->members.begin(),value->members.end(),[&](const auto& part){
                const auto& origin=part.object;
                return origin.id==target.id&&origin.generation==target.generation&&origin.guid==candidate->definition.guid&&
                    origin.source==session_resource_key(session_context->game_root,candidate->source)&&
                    origin.asset==candidate->asset&&origin.definition_chunk_id==candidate->chunk_id&&
                    origin.master_guid==object->definition->master_guid;
            });
            if(member!=value->members.end())info.content.refund=object_values->refund(target).amount;
        }
        const auto groups=live_physical_groups();
        const auto group=std::find_if(groups.begin(),groups.end(),[&](const auto& value){return value.complete&&
            std::any_of(value.members.begin(),value.members.end(),[&](const auto& part){return part.id==target.id&&part.generation==target.generation;});});
        if(group==groups.end()||group->members.size()>64)return info;
        for(const auto part:group->members){
            const auto* e=world.find(part.id);
            if(!e||e->generation!=part.generation||!e->definition||!render_lot)return {};
            const auto graphic=render_lot->entity_graphics(part.id);
            if(graphic.generation!=part.generation)return {};
            const odh::VmFrame frame{odh::routine_key(4096),0,{e->id,e->id,e->id,0},{},{}};
            const auto draw_graphic=world.read(frame,3,0);
            if(!draw_graphic){info.visuals.clear();return info;}
            SavedObjectVisual visual{e->id,e->definition->guid,*draw_graphic,graphic.direction,graphic.tile_position,{}};
            visual.dynamic_sprite_flags=odh::dynamic_sprite_flag_values(*e);
            info.visuals.push_back(std::move(visual));
        }
#ifdef ODH_HAVE_LINUX_SESSION_LOG
        session_log.event("UI pickup id="+std::to_string(target.id)+" name="+info.content.name+
            " refund="+(info.content.refund?std::to_string(*info.content.refund):"unknown")+
            " can_sell="+(info.content.can_sell?(*info.content.can_sell?"true":"false"):"unknown")+
            " parts="+std::to_string(info.visuals.size()));
#endif
        return info;
    };
    buy_services.visual_tile_position=[&](const odh::EntityPosition& position){
        if(!render_lot)throw odh::FormatError("buy preview needs its actual lot terrain");
        return render_lot->preview_tile_position(position);
    };
    odh_host::BuildModeServices build_services;
    build_services.ground_pick=[&](std::int32_t x,std::int32_t y)->std::optional<odh_host::BuildModePoint>{
        if(!render_lot||render_lot_view.level<1||render_lot_view.level>2)return {};
        const auto& architecture=render_lot->runtime_architecture_resource().architecture;
        const auto floor_z=static_cast<float>(render_lot_view.level-1)*2.95f;
        auto point=odh::unproject_tile(render_camera,static_cast<float>(x),static_cast<float>(y),floor_z);
        // Keep the continuous ground-plane position used by the reference UI.
        // Reconcile the real rendered terrain, without quantizing to a tile
        // ID or inventing a target object/VM placement proof.
        for(unsigned n=0;n<16;++n){
            if(point[0]<0||point[1]<0||point[0]>=architecture.width||point[1]>=architecture.height)return {};
            const auto z=floor_z+odh::terrain_interp_altitude(architecture,point[0],point[1]);
            const auto next=odh::unproject_tile(render_camera,static_cast<float>(x),static_cast<float>(y),z);
            if(std::abs(next[0]-point[0])<0.0001f&&std::abs(next[1]-point[1])<0.0001f)
                return odh_host::BuildModePoint{next[0],next[1],static_cast<std::int8_t>(render_lot_view.level)};
            point=next;
        }
        return {}; // No authenticated intersection on this rendered terrain.
    };
#endif
