        state.values[static_cast<std::size_t>(odh_host::OriginalSettingId::auto_center)]=player_preferences.auto_center;
        state.values[static_cast<std::size_t>(odh_host::OriginalSettingId::edge_scrolling)]=player_preferences.edge_scrolling;
