        const auto* neighbor=neighbors?neighbors->by_id(id):nullptr;
        if(!neighbor||retired_neighbor_ids.count(id)||retired_neighbor_guids.count(neighbor->guid))return {};
        odh_host::LiveRelationshipInfo info;info.neighbor_id=id;
        // NBRS.name is a character resource key, not a player-facing name.
        // Share the map's authenticated CTSS decoder; absent names remain absent.
        if(ui_neighbor_names)info.name=ui_neighbor_names->name(neighbor->guid);
        if(const auto instance=neighbors->instance_id(world,id);instance&&*instance>0)
            if(const auto* person=world.find(*instance);person&&person->name_override)info.name=*person->name_override;
        if(portrait&&ui_neighbor_portraits)if(const auto* image=ui_neighbor_portraits->get(neighbor->guid))
            info.portrait=std::make_shared<const odh::BitmapImage>(*image);
