    std::optional<odh::BitmapImage> visible_dialog_image;
    std::optional<odh::WorldEntityReference> visible_dialog_entity;
    std::optional<std::int16_t> visible_dialog_neighbor;
    const auto dialog_key=[](const odh::DialogState& state){return std::make_tuple(
        state.thread_owner.id,state.thread_owner.generation,state.run_generation,state.ticket);};
    prepare_dialog_art=[&](const odh::DialogState& state){
        visible_dialog_image.reset();visible_dialog_entity.reset();visible_dialog_neighbor.reset();
        try{
            odh::DialogStringScope scope;
            if(state.instruction.opcode==36)scope=odh::DialogStringScope::private_resource;
            else if(state.instruction.opcode==38)scope=odh::DialogStringScope::global_resource;
            else if(state.instruction.opcode==39)scope=odh::DialogStringScope::semiglobal_resource;
            else return;
            const auto resource=dialog_resource_for(scope,state.source);
            odh_host::DialogIllustrationSource subjects;
            const auto raw_neighbor=state.source.context.stack_object;
            subjects.neighbor_known=true;
            if(neighbor_ui_info(raw_neighbor,false))subjects.neighbor_id=raw_neighbor;
            const auto mode=(state.instruction.operands[7]>>1)&7;
            if(mode==0){
                subjects.automatic_known=true;
                const auto tables=load_strings(resource,{301});const auto table=tables.find(301);
                if(table==tables.end())return;
                // Original cTSString expansion writes an icon subject only for
                // $Object, then $Neighbor, in each of these five fields. This
                // order is independent of where the tokens appear in the text.
                const auto& op=state.instruction.operands;
                for(const auto id:{op[3],op[4],op[0],op[6],op[2]}){
                    if(!id)continue;
                    const auto* entry=odh::string_in_language_or_english(table->second,game_language,id-1);
                    if(!entry)continue;
                    bool object=false,neighbor=false;
                    odh::expand_dialog_text(entry->value,[&](std::string_view token,const auto&)->std::optional<std::string>{
                        object=object||token=="Object";neighbor=neighbor||token=="Neighbor";return std::string{};});
                    if(object)if(const auto* entity=world.frame_entity(state.source,odh::VmEntityRole::stack_object)){
                        subjects.automatic_entity=odh::WorldEntityReference{entity->id,entity->generation};subjects.automatic_neighbor_id.reset();
                    }
                    if(neighbor&&subjects.neighbor_id){subjects.automatic_neighbor_id=subjects.neighbor_id;subjects.automatic_entity.reset();}
                }
                if(!subjects.automatic_entity&&!subjects.automatic_neighbor_id)
                    if(const auto* entity=world.frame_entity(state.source,odh::VmEntityRole::stack_object))
                        subjects.automatic_entity=odh::WorldEntityReference{entity->id,entity->generation};
            }
            auto illustration=odh_host::prepare_dialog_illustration(state,world,subjects,
                odh_host::DialogIllustrationResource{resource.archive,resource.standalone?std::string{}:resource.entry,resource.frozen});
            const odh::BitmapImage* portrait=nullptr;
            if(illustration.plan.kind==odh_host::DialogIllustrationKind::neighbor&&illustration.plan.neighbor_id){
                const auto info=neighbor_ui_info(*illustration.plan.neighbor_id,true);
                if(info&&info->portrait){visible_dialog_image=*info->portrait;portrait=&*visible_dialog_image;
                    visible_dialog_neighbor=illustration.plan.neighbor_id;}
            }else if(illustration.plan.kind==odh_host::DialogIllustrationKind::entity&&illustration.plan.entity){
                visible_dialog_entity=illustration.plan.entity;
                const auto* entity=world.resolve_reference(*visible_dialog_entity);
                if(entity&&entity->definition){
                    if(entity->kind==odh::EntityKind::avatar){
                        (void)household_selector_portrait(entity->id,entity->definition->guid);
                        const auto cached=household_portrait_cache.find(entity->id);
                        const auto npc=npc_portrait_cache.find(entity->id);
                        if(cached!=household_portrait_cache.end()&&cached->second.panel_head)portrait=&*cached->second.panel_head;
                        else if(npc!=npc_portrait_cache.end()&&npc->second.panel_head)portrait=&*npc->second.panel_head;
                    }else if(definition_index){
                        if(!queue_view)queue_view.emplace(session_context->game_root);
                        portrait=queue_view->object_icon(*definition_index,entity->definition->guid);
                    }
                }
            }
            if(portrait&&original_dialog_art&&original_control_panel){
                // The original SimStub is the authored 133x103 blue halo;
                // its central 45px frame uses the actual front-facing head.
                const auto* backdrop=original_dialog_art->find("CPanel/SimStub.bmp");
                if(backdrop){
                    odh::RasterFrame frame;frame.width=backdrop->width;frame.height=backdrop->height;frame.pixels=backdrop->pixels;
                    const odh::UiBitmapRect icon_box{int(frame.width/2)-22,int(frame.height/2)-22,45,45};
                    const auto* subject=visible_dialog_entity?world.resolve_reference(*visible_dialog_entity):nullptr;
                    const bool object_icon=subject&&subject->kind!=odh::EntityKind::avatar;
                    original_control_panel->draw_portrait(frame,icon_box,false,object_icon?nullptr:portrait);
                    if(object_icon&&queue_view)queue_view->draw_object_icon(frame,icon_box,*portrait);
                    visible_dialog_image=odh::BitmapImage{frame.width,frame.height,24,true,std::move(frame.pixels),0};
                }else visible_dialog_image=*portrait;
            }else if(illustration.image)visible_dialog_image=std::move(illustration.image);
#ifdef ODH_HAVE_LINUX_SESSION_LOG
            session_log.event("UI dialog illustration kind="+std::to_string(static_cast<int>(illustration.plan.kind))+
                " opcode="+std::to_string(state.instruction.opcode));
#endif
        }catch(const std::exception& error){
#ifdef ODH_HAVE_LINUX_SESSION_LOG
            session_log.event(std::string("UI dialog illustration unavailable: ")+error.what());
#endif
            visible_dialog_image.reset();
        }
    };
    dialog_image_provider=[&](const odh::DialogState& state)->const odh::BitmapImage*{
        if(!dialog_view_key||*dialog_view_key!=dialog_key(state))return nullptr;
        if(visible_dialog_entity){
            const auto* entity=world.resolve_reference(*visible_dialog_entity);
            if(!world.is_live_reference(*visible_dialog_entity)||!entity||entity->dead)return nullptr;
        }
        if(visible_dialog_neighbor&&!neighbor_ui_info(*visible_dialog_neighbor,false))return nullptr;
        return visible_dialog_image?&*visible_dialog_image:nullptr;
    };
