                if(!created||host_failed)throw odh::FormatError("global-controller startup failed for resource "+definition->asset+": "+last_create_object_diagnostic);
                if(created->self_deleted)record.self_deleted=odh::WorldEntityReference{created->id,created->generation};
                else record.admitted=odh::WorldEntityReference{created->id,created->generation};
