                std::optional<odh::ObjdWallAppearance> binding;
                with_resource(Resource{def->source,def->asset,def->asset.empty()},[&](const auto& bytes){
                    odh::iff_chunks(bytes,[&](const auto& chunk){if(chunk.type=="OBJD"&&chunk.id==def->chunk_id)binding=odh::read_objd_wall_appearance(chunk.payload);});});
                if(!binding)throw odh::FormatError("recovery wall style unavailable");
