            if(live->dead)throw odh::FormatError("source Load2 deferred-dead class adapter is unavailable");
            if(live->kind==odh::EntityKind::avatar||!live->entry_points||live->entry_points->size()<=2)return;
            const auto action=live->entry_points->at(2).action;if(action<=255)return;
